// table built from a smooth function (as real DeePMD compression does).

namespace {

constexpr double kStep = 1.0e-6;

// Smooth per-layer functions and their first two derivatives.
double fl(int l, double x) {
  return (0.5 + 0.2 * l) * std::sin(0.9 * x + 0.2 + 0.3 * l) + 0.15 * l * x * x;
}
double fl_d(int l, double x) {
  return (0.5 + 0.2 * l) * 0.9 * std::cos(0.9 * x + 0.2 + 0.3 * l) + 0.30 * l * x;
}
double fl_dd(int l, double x) {
  return -(0.5 + 0.2 * l) * 0.81 * std::sin(0.9 * x + 0.2 + 0.3 * l) + 0.30 * l;
}

// Build a C2 piecewise-quintic table on the given grid (one segment per
// [grid[i], grid[i+1]]). Each segment stores 6 coeff (a0..a5) in local coord.
std::vector<double> make_c2_table(const std::vector<double>& grid,
                                  int last_layer_size) {
  const int nseg = (int)grid.size() - 1;
  std::vector<double> table(nseg * last_layer_size * 6, 0.0);
  for (int i = 0; i < nseg; ++i) {
    const double h = grid[i + 1] - grid[i];
    for (int l = 0; l < last_layer_size; ++l) {
      const double f0 = fl(l, grid[i]), f1 = fl(l, grid[i + 1]);
      const double g0 = fl_d(l, grid[i]), g1 = fl_d(l, grid[i + 1]);
      const double h0 = fl_dd(l, grid[i]), h1 = fl_dd(l, grid[i + 1]);
      const double a0 = f0;
      const double a1 = g0;
      const double a2 = h0 / 2.0;
      const double R0 = f1 - a0 - a1 * h - a2 * h * h;
      const double R1 = g1 - a1 - 2.0 * a2 * h;
      const double R2 = h1 - 2.0 * a2;
      const double c0 = R0 / (h * h * h);
      const double c1 = R1 / (h * h);
      const double c2 = R2 / h;
      const double d1 = c1 - 3.0 * c0;
      const double d2 = c2 - 6.0 * c0;
      const double a3 = c0 - 4.0 * d1 + d2 / 2.0;
      const double a4 = (7.0 * d1 - d2) / h;
      const double a5 = (d2 - 6.0 * d1) / (2.0 * h * h);
      const int b = i * last_layer_size * 6 + l * 6;
      table[b + 0] = a0;
      table[b + 1] = a1;
      table[b + 2] = a2;
      table[b + 3] = a3;
      table[b + 4] = a4;
      table[b + 5] = a5;
    }
  }
  return table;
}

