const std::vector<double> B_info = {B_lower, B_upper, B_max, B_s0, B_s1, -1.0};
const std::vector<double> B_w = {0.8, -0.45};
std::vector<double> B_grid() {
  std::vector<double> g;
  for (double x = -B_max; x < B_lower - 1e-9; x += B_s1) g.push_back(x);
  g.push_back(B_lower);
  for (double x = B_lower + B_s0; x < B_upper - 1e-9; x += B_s0) g.push_back(x);
  g.push_back(B_upper);
  for (double x = B_upper + B_s1; x < B_max - 1e-9; x += B_s1) g.push_back(x);
  g.push_back(B_max);
  return g;
}
double se_t_val(const std::vector<double>& t, double x) {
  std::vector<double> out(B_ll); const std::vector<double> ex = {x};
  deepmd::tabulate_fusion_se_t_cpu<double>(out.data(), t.data(), B_info.data(),
      ex.data(), ex.data(), 1, 1, 1, B_ll);
  double v = 0; for (int i = 0; i < B_ll; ++i) v += out[i] * B_w[i]; return v;
}
double se_t_sens(const std::vector<double>& t, double x) {
  // se_t: ll == em_x, so total d(value)/dx = dy_dem_x + dy_dem
  std::vector<double> dx(1), dem(1); const std::vector<double> ex = {x};
  deepmd::tabulate_fusion_se_t_grad_cpu<double>(dx.data(), dem.data(),
      t.data(), B_info.data(), ex.data(), ex.data(), B_w.data(), 1, 1, 1, B_ll);
  return dx[0] + dem[0];
}
double se_t_tebd_val(const std::vector<double>& t, double x) {
  std::vector<double> out(1 * 1 * B_ll); const std::vector<double> ex = {x};
  deepmd::tabulate_fusion_se_t_tebd_cpu<double>(out.data(), t.data(),
      B_info.data(), ex.data(), ex.data(), 1, 1, 1, B_ll);
  double v = 0; for (int i = 0; i < B_ll; ++i) v += out[i] * B_w[i]; return v;
}
double se_t_tebd_sens(const std::vector<double>& t, double x) {
  std::vector<double> dx(1); const std::vector<double> ex = {x};
  deepmd::tabulate_fusion_se_t_tebd_grad_cpu<double>(dx.data(), t.data(),
      B_info.data(), ex.data(), ex.data(), B_w.data(), 1, 1, 1, B_ll);
  return dx[0];
}

}  // namespace

int main() {
  auto tA = make_c2_table(A_grid(), A_ll);
  std::vector<double> ptsA = {A_lower - 0.4, A_lower - 0.2, A_lower,
      A_lower + 0.4, A_upper, 1.3, A_upper + 1.6, A_max - 0.3, A_max,
      A_max + 0.4, A_max + 0.9, A_max + 2.0};
  report(\"se_r      (double)\", sweep(
      [&](double x){return se_r_val(tA,x);},
      [&](double x){return se_r_sens(tA,x);}, ptsA));
  report(\"se_a      (double)\", sweep(
      [&](double x){return se_a_val(tA,x);},
      [&](double x){return se_a_sens(tA,x);}, ptsA));

  auto tB = make_c2_table(B_grid(), B_ll);
  std::vector<double> ptsB = {-B_max - 0.5, -B_max, -B_max + 0.3, -1.0, B_lower,
      0.7, B_upper, B_upper + 0.6, B_max, B_max + 0.4, B_max + 1.1};
  report(\"se_t      (double)\", sweep(
      [&](double x){return se_t_val(tB,x);},
      [&](double x){return se_t_sens(tB,x);}, ptsB));
  report(\"se_t_tebd (double)\", sweep(
      [&](double x){return se_t_tebd_val(tB,x);},
      [&](double x){return se_t_tebd_sens(tB,x);}, ptsB));

  // ---- float precision (locate_xx is templated) ----
  {
    std::vector<float> tAf(tA.size());
    for (std::size_t i = 0; i < tA.size(); ++i) tAf[i] = (float)tA[i];
    std::vector<float> infoF(A_info.size());
    for (std::size_t i = 0; i < A_info.size(); ++i) infoF[i] = (float)A_info[i];
    std::vector<float> wF(A_w.size());
    for (std::size_t i = 0; i < A_w.size(); ++i) wF[i] = (float)A_w[i];
    auto val = [&](double x)->double{
      std::vector<float> out(A_ll); const float em[1] = {(float)x};
      deepmd::tabulate_fusion_se_r_cpu<float>(out.data(), tAf.data(),
          infoF.data(), em, 1, 1, A_ll);
      double v = 0; for (int i = 0; i < A_ll; ++i) v += out[i] * wF[i]; return v;
    };
    auto sens = [&](double x)->double{
      std::vector<float> dy(1); const float em[1] = {(float)x};
      deepmd::tabulate_fusion_se_r_grad_cpu<float>(dy.data(), tAf.data(),
          infoF.data(), em, wF.data(), 1, 1, A_ll);
      return dy[0];
    };
    report(\"se_r      (float )\", sweep(val, sens, ptsA));
  }
  return 0;
}
