// Confirm the float \"gap\" is FD cancellation, not a locate_xx bug: use a
// float-optimal step (eps"'^(1/3) ~ 6e-3) and inspect per-point behaviour.
namespace {
constexpr double A_lower=0.5,A_upper=2.0,A_max=4.5,A_s0=0.3,A_s1=0.5;
constexpr int A_ll=4;
const std::vector<double> A_info={A_lower,A_upper,A_max,A_s0,A_s1,-1.0};
const std::vector<double> A_w={0.6,-0.35,0.22,0.11};
double fl(int l,double x){return (0.5+0.2*l)*std::sin(0.9*x+0.2+0.3*l)+0.15*l*x*x;}
double fld(int l,double x){return (0.5+0.2*l)*0.9*std::cos(0.9*x+0.2+0.3*l)+0.30*l*x;}
double fldd(int l,double x){return -(0.5+0.2*l)*0.81*std::sin(0.9*x+0.2+0.3*l)+0.30*l;}
std::vector<double> grid(){std::vector<double> g;for(double x=A_lower;x<A_upper-1e-9;x+=A_s0)g.push_back(x);g.push_back(A_upper);for(double x=A_upper+A_s1;x<A_max-1e-9;x+=A_s1)g.push_back(x);g.push_back(A_max);return g;}
std::vector<float> c2f(){auto g=grid();int n=g.size()-1;std::vector<float> t(n*A_ll*6,0);for(int i=0;i<n;++i){double h=g[i+1]-g[i];for(int l=0;l<A_ll;++l){double a0=fl(l,g[i]),a1=fld(l,g[i]),a2=fldd(l,g[i])/2;double R0=fl(l,g[i+1])-a0-a1*h-a2*h*h,R1=fld(l,g[i+1])-a1-2*a2*h,R2=fldd(l,g[i+1])-2*a2;double c0=R0/(h*h*h),c1=R1/(h*h),c2=R2/h,d1=c1-3*c0,d2=c2-6*c0;double a3=c0-4*d1+d2/2,a4=(7*d1-d2)/h,a5=(d2-6*d1)/(2*h*h);int b=i*A_ll*6+l*6;t[b+0]=(float)a0;t[b+1]=(float)a1;t[b+2]=(float)a2;t[b+3]=(float)a3;t[b+4]=(float)a4;t[b+5]=(float)a5;}}return t;}
float valf(const std::vector<float>&t,float info[6],float w[4],float x){float out[4];const float em[1]={x};deepmd::tabulate_fusion_se_r_cpu<float>(out,t.data(),info,em,1,1,A_ll);float v=0;for(int i=0;i<A_ll;++i)v+=out[i]*w[i];return v;}
float sensf(const std::vector<float>&t,float info[6],float w[4],float x){float dy[1];const float em[1]={x};deepmd::tabulate_fusion_se_r_grad_cpu<float>(dy,t.data(),info,em,w,1,1,A_ll);return dy[0];}
}
int main(){
  auto t=c2f();float info[6],w[4];for(int i=0;i<6;++i)info[i]=(float)A_info[i];for(int i=0;i<4;++i)w[i]=(float)A_w[i];
  std::vector<double> pts={A_lower-0.4,A_lower,A_upper,A_max,A_max+0.4,A_max+0.9};
  for(double hstep:{1e-6,6e-3}){
    std::cout<<"--- float step="<<hstep<<" ---'"\\n\";
    double worst=0;
    for(double x:pts){
      float xf=(float)x;
      float cd=(valf(t,info,w,(float)(x+hstep))-valf(t,info,w,(float)(x-hstep)))/(float)(2*hstep);
      float s=sensf(t,info,w,xf);
      double gap=std::fabs((double)cd-(double)s);
      worst=std::max(worst,gap);
      std::cout<<std::scientific<<std::setprecision(3)<<\"x=\"<<x<<\" sens=\"<<s<<\" fd=\"<<cd<<\" gap=\"<<gap<<\"\\n\";
    }
    std::cout<<\"worst=\"<<worst<<\"\\n\";
  }
  return 0;
}
